  // Sticky nav surface on scroll
  var nav = document.getElementById('nav');
  var onScroll = function () {
    nav.classList.toggle('scrolled', window.scrollY > 24);
  };
  onScroll();
  window.addEventListener('scroll', onScroll, { passive: true });

  // Mobile menu
  var toggle = document.getElementById('menuToggle');
  var menu = document.getElementById('menu');
  toggle.addEventListener('click', function () {
    var open = !menu.classList.contains('open');
    menu.classList.toggle('open', open);
    toggle.setAttribute('aria-expanded', String(open));
    toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
  });
  menu.querySelectorAll('a').forEach(function (a) {
    a.addEventListener('click', function () {
      menu.classList.remove('open');
      toggle.setAttribute('aria-expanded', 'false');
      toggle.setAttribute('aria-label', 'Open menu');
    });
  });

  // Timetable selection
  var body = document.getElementById('timetableBody');
  var label = document.querySelector('#selectionText span') || document.getElementById('selectionText');
  body.addEventListener('click', function (e) {
    var btn = e.target.closest('.select-btn');
    if (!btn || btn.disabled) return;
    var row = btn.closest('tr');
    var wasActive = btn.classList.contains('active');

    body.querySelectorAll('tr').forEach(function (r) { r.classList.remove('is-selected'); });
    body.querySelectorAll('.select-btn').forEach(function (b) {
      if (!b.disabled) { b.classList.remove('active'); b.textContent = 'Select'; }
    });

    if (!wasActive) {
      row.classList.add('is-selected');
      btn.classList.add('active');
      btn.textContent = 'Selected';
      var dep = row.querySelector('td:nth-child(2) .time').textContent;
      var arr = row.querySelector('td:nth-child(3) .time').textContent;
      var name = row.getAttribute('data-service');
      label.innerHTML = '';
      var strong = document.createElement('strong');
      strong.textContent = name;
      label.appendChild(strong);
      label.appendChild(document.createTextNode('  ·  departs ' + dep + ', arrives ' + arr));
    } else {
      label.textContent = 'No departure selected yet. Choose a service above.';
    }
  });

  // Reveal on scroll
  var items = document.querySelectorAll('.reveal');
  if ('IntersectionObserver' in window) {
    var io = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          entry.target.classList.add('in');
          io.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
    items.forEach(function (el) { io.observe(el); });
  } else {
    items.forEach(function (el) { el.classList.add('in'); });
  }
})();
</script>
